import { describe, expect, it } from "vitest"
import { groupKey, isComplete, matchesFilter, readFilter, type FilterCondition } from "./client-filters"
import type { ClientFigures } from "./client-figures"
import { ClientStatus, type Client } from "../../types/workforce"

const client = (o: Partial<Client> = {}): Client => ({
  id: "c", workspaceId: "w", name: "Acme", email: "a@x.example", status: ClientStatus.ACTIVE, paymentTermsDays: 30, contacts: [], createdAt: "", updatedAt: "", ...o,
})
const fig = (o: Partial<ClientFigures> = {}) => ({
  projects: { total: 2, inProgress: 1, completed: 1, cancelled: 0 }, openDeals: { count: 1, amount: 10, weighted: 5 },
  outstanding: 5000, overdue: 0, lastContact: "2026-03-01", health: { level: "good", reasons: [] }, ...o,
}) as unknown as ClientFigures
const cond = (field: FilterCondition["field"], op: FilterCondition["op"], value?: string): FilterCondition => ({ id: field + op, field, op, value })
const today = "2026-03-31"

describe("client filters (CRM step 10)", () => {
  it("joins conditions with AND or OR", () => {
    const c = client({ tags: ["VIP", "Europe"], accountManagerId: "emp_1" })
    const f = fig()
    const vip = cond("tag", "is", "VIP")
    const lead = cond("status", "is", ClientStatus.LEAD)
    expect(matchesFilter(c, f, { mode: "all", conditions: [vip, lead] }, today)).toBe(false)
    expect(matchesFilter(c, f, { mode: "any", conditions: [vip, lead] }, today)).toBe(true)
    expect(matchesFilter(c, f, { mode: "all", conditions: [] }, today)).toBe(true)
  })

  it("compares numbers, empty values and days since the last contact", () => {
    const f = fig()
    expect(matchesFilter(client(), f, { mode: "all", conditions: [cond("owed", "gt", "4000")] }, today)).toBe(true)
    expect(matchesFilter(client(), f, { mode: "all", conditions: [cond("owed", "lt", "4000")] }, today)).toBe(false)
    expect(matchesFilter(client(), f, { mode: "all", conditions: [cond("daysSinceContact", "gt", "29")] }, today)).toBe(true)
    expect(matchesFilter(client(), fig({ lastContact: undefined }), { mode: "all", conditions: [cond("daysSinceContact", "gt", "365")] }, today)).toBe(true)
    expect(matchesFilter(client(), f, { mode: "all", conditions: [cond("manager", "isEmpty")] }, today)).toBe(true)
    expect(matchesFilter(client({ accountManagerId: "e" }), f, { mode: "all", conditions: [cond("manager", "isNot", "e")] }, today)).toBe(false)
  })

  it("ignores unfinished conditions and bad saved data", () => {
    expect(isComplete(cond("tag", "is"))).toBe(false)
    expect(isComplete(cond("owed", "gt", "abc"))).toBe(false)
    expect(isComplete(cond("tag", "isEmpty"))).toBe(true)
    expect(matchesFilter(client(), fig(), { mode: "all", conditions: [cond("tag", "is")] }, today)).toBe(true)
    expect(readFilter({ mode: "any", conditions: [cond("tag", "is", "A"), { id: "x", field: "nope", op: "is" }] })).toEqual({ mode: "any", conditions: [cond("tag", "is", "A")] })
    expect(readFilter("junk")).toEqual({ mode: "all", conditions: [] })
  })

  it("groups by a field, empty values in their own group", () => {
    expect(groupKey(client({ industry: "Retail" }), fig(), "industry")).toBe("Retail")
    expect(groupKey(client(), fig(), "industry")).toBe("")
    expect(groupKey(client(), fig(), "health")).toBe("good")
  })
})
